import{_ as a,o as r,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const t="/assets/images/h81n9iK.png",g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/load-balancer.md","filePath":"core-concepts/load-balancer.md"}'),o={name:"core-concepts/load-balancer.md"};function l(s,e,c,d,h,p){return r(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="load-balancer" tabindex="-1">Load balancer <a class="header-anchor" href="#load-balancer" aria-label="Permalink to &quot;Load balancer&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Load balancer.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+t+'"><br><i><a href="http://horicky.blogspot.com/2010/10/scalable-system-design-patterns.html">Source: Scalable system design patterns</a></i></p><p>Load balancers distribute incoming client requests to computing resources such as application servers and databases. In each case, the load balancer returns the response from the computing resource to the appropriate client. Load balancers are effective at:</p><ul><li>Preventing requests from going to unhealthy servers</li><li>Preventing overloading resources</li><li>Helping to eliminate a single point of failure</li></ul><p>Load balancers can be implemented with hardware (expensive) or with software such as HAProxy.</p><p>Additional benefits include:</p><ul><li><strong>SSL termination</strong> - Decrypt incoming requests and encrypt server responses so backend servers do not have to perform these potentially expensive operations <ul><li>Removes the need to install <a href="https://en.wikipedia.org/wiki/X.509" target="_blank" rel="noreferrer">X.509 certificates</a> on each server</li></ul></li><li><strong>Session persistence</strong> - Issue cookies and route a specific client&#39;s requests to same instance if the web apps do not keep track of sessions</li></ul><p>To protect against failures, it&#39;s common to set up multiple load balancers, either in <a href="#active-passive">active-passive</a> or <a href="#active-active">active-active</a> mode.</p><p>Load balancers can route traffic based on various metrics, including:</p><ul><li>Random</li><li>Least loaded</li><li>Session/cookies</li><li><a href="https://www.g33kinfo.com/info/round-robin-vs-weighted-round-robin-lb" target="_blank" rel="noreferrer">Round robin or weighted round robin</a></li><li><a href="#layer-4-load-balancing">Layer 4</a></li><li><a href="#layer-7-load-balancing">Layer 7</a></li></ul><h3 id="layer-4-load-balancing" tabindex="-1">Layer 4 load balancing <a class="header-anchor" href="#layer-4-load-balancing" aria-label="Permalink to &quot;Layer 4 load balancing&quot;">​</a></h3><p>Layer 4 load balancers look at info at the <a href="/core-concepts/communication.html">transport layer</a> to decide how to distribute requests. Generally, this involves the source, destination IP addresses, and ports in the header, but not the contents of the packet. Layer 4 load balancers forward network packets to and from the upstream server, performing <a href="https://web.archive.org/web/20240117134735/https://www.nginx.com/resources/glossary/layer-4-load-balancing/" target="_blank" rel="noreferrer">Network Address Translation (NAT)</a>.</p><h3 id="layer-7-load-balancing" tabindex="-1">Layer 7 load balancing <a class="header-anchor" href="#layer-7-load-balancing" aria-label="Permalink to &quot;Layer 7 load balancing&quot;">​</a></h3><p>Layer 7 load balancers look at the <a href="/core-concepts/communication.html">application layer</a> to decide how to distribute requests. This can involve contents of the header, message, and cookies. Layer 7 load balancers terminate network traffic, reads the message, makes a load-balancing decision, then opens a connection to the selected server. For example, a layer 7 load balancer can direct video traffic to servers that host videos while directing more sensitive user billing traffic to security-hardened servers.</p><p>At the cost of flexibility, layer 4 load balancing requires less time and computing resources than Layer 7, although the performance impact can be minimal on modern commodity hardware.</p><h3 id="horizontal-scaling" tabindex="-1">Horizontal scaling <a class="header-anchor" href="#horizontal-scaling" aria-label="Permalink to &quot;Horizontal scaling&quot;">​</a></h3><p>Load balancers can also help with horizontal scaling, improving performance and availability. Scaling out using commodity machines is more cost efficient and results in higher availability than scaling up a single server on more expensive hardware, called <strong>Vertical Scaling</strong>. It is also easier to hire for talent working on commodity hardware than it is for specialized enterprise systems.</p><h4 id="disadvantage-s-horizontal-scaling" tabindex="-1">Disadvantage(s): horizontal scaling <a class="header-anchor" href="#disadvantage-s-horizontal-scaling" aria-label="Permalink to &quot;Disadvantage(s): horizontal scaling&quot;">​</a></h4><ul><li>Scaling horizontally introduces complexity and involves cloning servers <ul><li>Servers should be stateless: they should not contain any user-related data like sessions or profile pictures</li><li>Sessions can be stored in a centralized data store such as a <a href="/core-concepts/database.html">database</a> (SQL, NoSQL) or a persistent <a href="/core-concepts/cache.html">cache</a> (Redis, Memcached)</li></ul></li><li>Downstream servers such as caches and databases need to handle more simultaneous connections as upstream servers scale out</li></ul><h3 id="disadvantage-s-load-balancer" tabindex="-1">Disadvantage(s): load balancer <a class="header-anchor" href="#disadvantage-s-load-balancer" aria-label="Permalink to &quot;Disadvantage(s): load balancer&quot;">​</a></h3><ul><li>The load balancer can become a performance bottleneck if it does not have enough resources or if it is not configured properly.</li><li>Introducing a load balancer to help eliminate a single point of failure results in increased complexity.</li><li>A single load balancer is a single point of failure, configuring multiple load balancers further increases complexity.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://www.nginx.com/blog/inside-nginx-how-we-designed-for-performance-scale/" target="_blank" rel="noreferrer">NGINX architecture</a></li><li><a href="http://www.haproxy.org/download/1.2/doc/architecture.txt" target="_blank" rel="noreferrer">HAProxy architecture guide</a></li><li><a href="https://web.archive.org/web/20220530193911/https://www.lecloud.net/post/7295452622/scalability-for-dummies-part-1-clones" target="_blank" rel="noreferrer">Scalability</a></li><li><a href="https://en.wikipedia.org/wiki/Load_balancing_(computing)" target="_blank" rel="noreferrer">Wikipedia</a></li><li><a href="https://www.nginx.com/resources/glossary/layer-4-load-balancing/" target="_blank" rel="noreferrer">Layer 4 load balancing</a></li><li><a href="https://www.nginx.com/resources/glossary/layer-7-load-balancing/" target="_blank" rel="noreferrer">Layer 7 load balancing</a></li><li><a href="http://docs.aws.amazon.com/elasticloadbalancing/latest/classic/elb-listener-config.html" target="_blank" rel="noreferrer">ELB listener config</a></li></ul>',24)])])}const b=a(o,[["render",l]]);export{g as __pageData,b as default};
